      "presentIllness": "患者平素月经规律，LMP：{lmp}，EDC：{edc}。孕期定期产检，孕早、中期血压正常。{days}天前产检发现血压升高，最高{bp_max}mmHg，伴头痛、眼花、上腹部不适，无抽搐、意识障碍，无阴道流血、流液，胎动正常。复查尿蛋白阳性，追问病史，患者既往无高血压、糖尿病、肾病病史，无慢性高血压家族史；孕20周前血压正常，尿常规正常；孕期无头痛、眼花、视物模糊史，无外伤史，无阴道流血、流液；入院前门诊复查血压仍高，尿蛋白阳性，已予口服拉贝洛尔{pre_med}，血压控制欠佳；无抽搐、晕厥发作；患者否认吸烟、饮酒史，无药物过敏史；既往孕{grav}产{para}，孕期体重增加{weight_gain}kg；目前血压波动于{bp_now}mmHg，门诊查24小时尿蛋白定量{up_24h}g；胎动正常，无宫缩、无腹痛。患者近期精神紧张，睡眠欠佳，需住院规范降压及解痉治疗。。遂收入院。患者近期精神紧张，食欲、睡眠欠佳，胎动正常。",
      "pastHistory": "既往无高血压、糖尿病、肾病。否认有\"肝炎\"、\"结核\"史，否认手术史、外伤史、输血史。否认食物及药物过敏史。",
      "personalHistory": "原地出生，不吸烟，不饮酒。",
      "menstrualHistory": "平素月经规律，初潮{menarche}岁，周期{cycle}天，经期{period}天，末次月经{lmp}。",
