      "physicalExam": "发育正常，营养中等，神志清楚，查体合作。全身皮肤黏膜无黄染。头颈无畸形，巩膜无黄染，甲状腺未触及肿大。双侧呼吸音清，未闻及明显干湿性啰音；心界不大，心率齐，各瓣膜听诊区未闻及病理性杂音。腹平软，全腹无压痛及反跳痛，肝脾肋下未触及，肠鸣音正常。双下肢无水肿。脊柱四肢无畸形，生理反射存在，病理反射未引出。",
      "specialistExam": "血压{bp}mmHg。宫高{fh}cm，腹围{ac}cm，胎位{pos}，胎心{fhr}次/分。胎膜{membrane}，宫口{cx}cm。水肿程度：{edema}。胎心监护：NST反应型（基线135次/分，变异良好，无减速）。产前超声 Doppler 血流：S/D比值 2.3，RI 0.56，PI 0.82，羊水指数（AFI）{afi}cm。",
