      "diagnosticBasis": "1.妊娠24-28周行OGTT：空腹≥5.1mmol/L、1小时≥10.0mmol/L、2小时≥8.5mmol/L，任一项达标即可诊断\n2.可伴多饮、多食、多尿等表现",
      "treatmentOptions": "1.医学营养治疗：控制总热量，少食多餐\n2.运动治疗：餐后适当散步\n3.胰岛素治疗：饮食运动控制不达标时使用\n4.监测血糖：空腹及餐后2小时\n注：血糖控制不理想或合并酮症酸中毒时及时转诊",
