      "examOptional": "1.眼底检查（疑视网膜病变）\n2.肾功能及24小时尿蛋白（疑肾脏损害）",
      "medicationPlan": "1.胰岛素：按血糖水平个体化调整\n2.维生素及铁剂补充\n3.不推荐口服降糖药（妊娠期）",
      "surgeryDay": "非手术治疗；如血糖控制差、胎儿窘迫或合并其他产科指征，可适时终止妊娠",
      "postopRecovery": "1.产后监测血糖，多数患者血糖可恢复正常\n2.产后6-12周复查OGTT\n3.保持健康饮食及运动",
