    "presentIllness": "患者{months}月前无明显诱因出现腹胀，进食后加重，伴食欲下降、早饱感，无恶心、呕吐，无腹痛、腹泻，曾自行口服促消化药物（{gi_med}）效果不佳。此后腹胀逐渐加重，伴乏力、消瘦，体重下降约{weight_loss}kg，{days}天前自觉下腹部可触及一包块，质地较硬，活动度差，无压痛，伴腰酸，无发热，无阴道流血、排液。追问病史，患者无发热、盗汗，无咳嗽、咳痰，无恶心、呕吐，无排便习惯改变，无尿频、尿急；腹胀与进食相关，夜间及平卧位时加重，坐位稍缓解；近期腹围逐渐增大，需更换宽松衣物。。遂至我院就诊，妇科B超提示\"{side}附件区囊实性包块，大小约{size}×{size2}cm，边界不清，盆腔大量积液（腹水）\"，肿瘤标志物CA125 {ca125}U/ml明显升高，HE4 {he4}pmol/L，腹水细胞学{ascites_cytology}，拟\"卵巢恶性肿瘤\"收入院。发病以来，患者精神欠佳，食欲下降，睡眠可，二便正常，体重明显下降。",
